# Lunar Konstruksi - Structured Lines + Pinterest Asset Slots
# Polishes the Form/Work frontend without touching backend/admin.

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Phase([string]$Message) { Write-Host "[VISUAL POLISH] $Message" -ForegroundColor Cyan }
function Fail([string]$Message) { Write-Host ""; Write-Host "[VISUAL POLISH] GAGAL: $Message" -ForegroundColor Red; exit 1 }
function Write-Utf8NoBom([string]$Path, [string]$Content) {
  $parent = Split-Path -Parent $Path
  if ($parent -and -not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }
  $enc = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $enc)
}
function Decode([string]$Value) { [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value)) }

$repoRoot = (& git rev-parse --show-toplevel 2>$null)
if (-not $repoRoot) { Fail "Jalankan dari root repository Lunar Konstruksi." }
$repoRoot = $repoRoot.Trim()
Set-Location $repoRoot
Phase "Repo: $repoRoot"
$required = @(
  "components/site/formwork/home.tsx",
  "components/site/formwork/decor.tsx",
  "components/site/formwork/media.tsx",
  "components/site/formwork/data.ts"
)
$missing = @($required | Where-Object { -not (Test-Path -LiteralPath $_) })
if ($missing.Count -gt 0) { $missing | ForEach-Object { Write-Host "  - $_" }; Fail "Form/Work frontend belum terdeteksi. Terapkan redesign sebelumnya dulu." }

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $repoRoot ".lunar-backups/structured-lines-$stamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null
foreach ($path in @("components/site/formwork/home.tsx","components/site/formwork/decor.tsx","components/site/formwork/local-assets.ts")) {
  if (Test-Path -LiteralPath $path) {
    $dest = Join-Path $backupRoot $path
    $parent = Split-Path -Parent $dest
    New-Item -ItemType Directory -Force -Path $parent | Out-Null
    Copy-Item -LiteralPath $path -Destination $dest -Force
  }
}
Phase "Backup: $backupRoot"

$payload = @{}
$payload["components/site/formwork/decor.tsx"] = ""
$payload["components/site/formwork/home.tsx"] = ""
$payload["PINTEREST_ASSET_GUIDE.md"] = ""

foreach ($entry in $payload.GetEnumerator()) {
  $target = Join-Path $repoRoot $entry.Key
  Write-Utf8NoBom $target (Decode $entry.Value)
  Write-Host "[VISUAL POLISH] write $($entry.Key)" -ForegroundColor DarkGray
}

# Build local asset registry from images already present under public/.
$publicRoot = Join-Path $repoRoot "public"
$imageFiles = @()
if (Test-Path -LiteralPath $publicRoot) {
  $imageFiles = @(Get-ChildItem -LiteralPath $publicRoot -Recurse -File | Where-Object {
    $_.Extension -match "^\.(jpg|jpeg|png|webp|avif)$" -and $_.Name -notmatch "(?i)(logo|favicon|icon|qr|sprite)"
  })
}
$normalized = @($imageFiles | ForEach-Object {
  $rel = $_.FullName.Substring($publicRoot.Length).TrimStart("\","/").Replace("\","/")
  [PSCustomObject]@{ Name = $_.Name; Url = "/" + $rel }
})
$priority = @($normalized | Sort-Object @{Expression={ if ($_.Name -match "(?i)(hero|construction|konstruksi|building|site|crane|engineer|work)") {0} else {1} }}, Name)
$heroUrl = if ($priority.Count -gt 0) { $priority[0].Url } else { "" }
$decorativeUrls = @($priority | Where-Object { $_.Url -ne $heroUrl } | Select-Object -ExpandProperty Url -First 12)
$quotedDecorative = @($decorativeUrls | ForEach-Object { "  `"$($_)`"," }) -join "`n"
$localAssetSource = @"
export const LOCAL_MEDIA = {
  hero: "$heroUrl",
  aboutHero: "",
  servicesHero: "",
  projectsHero: "",
  decorative: [
$quotedDecorative
  ] as string[],
};

export function localMediaAt(index: number) {
  if (!LOCAL_MEDIA.decorative.length) return "";
  return LOCAL_MEDIA.decorative[index % LOCAL_MEDIA.decorative.length] ?? "";
}
"@
Write-Utf8NoBom (Join-Path $repoRoot "components/site/formwork/local-assets.ts") $localAssetSource
Write-Host "[VISUAL POLISH] write components/site/formwork/local-assets.ts" -ForegroundColor DarkGray

Write-Host ""
Write-Host "[VISUAL POLISH] Selesai." -ForegroundColor Green
Write-Host "- Grid blueprint hanya dipakai halus di hero." -ForegroundColor Green
Write-Host "- Orange curve hanya dipakai sebagai measurement guide yang terstruktur." -ForegroundColor Green
Write-Host "- CTA tidak lagi punya garis raksasa." -ForegroundColor Green
Write-Host "- Story images lokal tidak boleh reuse satu gambar berkali-kali." -ForegroundColor Green
Write-Host "- Entity cards tetap memakai media database masing-masing." -ForegroundColor Green
Write-Host ""
Write-Host "Kalau ingin visual Pinterest-quality, taruh file berizin di public/images/site/:" -ForegroundColor Yellow
Write-Host "  hero-construction.jpg"
Write-Host "  engineer-blueprint.jpg"
Write-Host "  capability-building.jpg"
Write-Host "  capability-field.jpg"
Write-Host "  capability-detail.jpg"
Write-Host "Lalu jalankan installer ini lagi agar registry local asset ter-refresh."
Write-Host ""
Write-Host "Validasi:" -ForegroundColor Cyan
Write-Host "  npm run lint"
Write-Host "  npm run typecheck"
Write-Host "  npm run build"
